def split_csv_line(line: str) -> list[str]:
    if line == '':
        return ['']
    fields: list[str] = []
    i, n = 0, len(line)
    while True:
        buf: list[str] = []
        if i < n and line[i] == '"':
            i += 1
            while i < n:
                if line[i] == '"':
                    if i + 1 < n and line[i + 1] == '"':
                        buf.append('"')
                        i += 2
                    else:
                        i += 1
                        break
                else:
                    buf.append(line[i])
                    i += 1
            while i < n and line[i] != ',':
                buf.append(line[i])
                i += 1
        else:
            while i < n and line[i] != ',':
                buf.append(line[i])
                i += 1
        fields.append(''.join(buf))
        if i < n and line[i] == ',':
            i += 1
        else:
            return fields
